constexpr std::complex<double> PI = {0.0, std::acos(-1.0)};
constexpr double LOG_SQRT_2PI = 0.5 * std::log(2.0 * PI.real());

if (n == 0) {
    return {1.0, 0.0};
}

double log_n_fact = 0.0;
if (n <= 20) {
    log_n_fact = std::lgamma(n + 1);
} else {
    double x = static_cast<double>(n);
    log_n_fact = (x + 0.5) * std::log(x) - x + LOG_SQRT_2PI;
}

double log_abs_alpha = std::log(std::abs(alpha));
double log_n_times_log_abs_alpha = n * log_abs_alpha;
double log_denominator = 0.5 * log_n_fact;

std::complex<double> alpha_pow_n = std::pow(alpha, static_cast<std::complex<double>>(n));
std::complex<double> denominator = std::exp(std::complex<double>(log_denominator, 0.0));

return alpha_pow_n / denominator;
// END_CODE

